def decode_nested_run_length(s):
    stack = []
    current = []
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            stack.append((current, num))
            current = []
            num = 0
        elif ch == ']':
            prev, count = stack.pop()
            prev.append(''.join(current) * count)
            current = prev
        else:
            current.append(ch)
