def zigzag_convert(s, n):
    if n <= 1 or n >= len(s):
        return s
    rows = [[] for _ in range(n)]
    row, step = 0, 1
    for ch in s:
        rows[row].append(ch)
        if row == 0:
            step = 1
        elif row == n - 1:
            step = -1
        row += step
    return ''.join(''.join(r) for r in rows)

